def max_accordion_length(s):
    stack = []
    max_length = 0
    current_length = 0

    for char in s:
        if char == '[':
            if stack and stack[-1] != ']':
                return -1
            stack.append(char)
            current_length += 1
        elif char == ']':
            if not stack or stack[-1] != '[':
                return -1
            stack.pop()
            current_length += 1
            max_length = max(max_length, current_length)
            current_length = 0
        elif char == ':':
            if not stack or stack[-1] != '[':
                return -1
            stack.append(char)
            current_length += 1
        elif char == '|':
            if not stack or stack[-1] != ':':
                return -1
            stack.append(char)
            current_length += 1

    if stack:
        return -1

